import dao.*;import model.*;import util.*;import view.loja.TelaLoja;import javax.swing.*;import java.awt.*;import java.awt.image.BufferedImage;import java.sql.*;import java.math.BigDecimal;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.function.BooleanSupplier;import javax.imageio.ImageIO;

/** Busca real no PostgreSQL e no formulário da loja; modo local só consulta. */
public final class BuscaProdutos {
 private static final ProdutoDAO dao=new ProdutoDAO();private static int casos;private static TelaLoja loja;
 public static void main(String[] args)throws Exception {
  boolean local=args.length==1 && args[0].equals("--local");exigir(texto("SELECT current_database()").equals(local?"obotbarato":"obotbarato_test"),"Base incorreta.");
  Thread limite=new Thread(()->{try{Thread.sleep(100000);}catch(InterruptedException e){return;}System.err.println("Busca excedeu limite.");System.exit(1);});limite.setDaemon(true);limite.start();Sessao.iniciar(new UsuarioDAO().autenticar("admin","admin123"));
  if(!local){
   int cat=new CategoriaDAO().listar(false).get(0).id();Produto oleo=produto("Óleo para Pontas ÁRGAN Pesquisa 60 ml",cat,true),creme=produto("Creme Ação Pesquisa",cat,true),cafe=produto("Cafe\u0301 Capi\u0301lar Pesquisa",cat,true),kit=produto("Kit_100% Cílios Pesquisa",cat,true),inativo=produto("Óleo Antigo Pesquisa",cat,false);
   int oculto;try(Connection c=ConexaoBanco.getConexao();Statement s=c.createStatement();ResultSet r=s.executeQuery("INSERT INTO categorias(nome) VALUES('Categoria Oculta Busca') RETURNING id")){r.next();oculto=r.getInt(1);}Produto categoriaInativa=produto("Óleo Oculto Pesquisa",oculto,true);sql("UPDATE categorias SET ativo=false WHERE id="+oculto);
   Set<Integer> esperado=ids("oleo pesquisa");for(String termo:new String[]{"ÓLEO PESQUISA","  oleo   pesquisa  ","o\u0301leo pesquisa","pesquisa oleo","oleo-pesquisa"})exigir(ids(termo).equals(esperado),"Busca divergente: "+termo);exigir(esperado.contains(oleo.getId()),"Óleo não encontrado.");ok("Acentos, caixa, espaços, ordem, hífen e Unicode decomposto equivalentes");
   exigir(ids("pesq arg ole").equals(Set.of(oleo.getId())) && ids("acao pesquisa").contains(creme.getId()) && ids("cafe capilar pesquisa").contains(cafe.getId()) && ids("cilios pesquisa").contains(kit.getId()),"Partes/acentos portugueses falharam.");ok("Partes do nome e acentos portugueses, incluindo ç e marcas combinadas");
   exigir(dao.buscarPorNome("argan oleo pesquisa").stream().anyMatch(p->p.getId()==oleo.getId()) && dao.listarManutencao("pesquisa OLEO").stream().anyMatch(p->p.getId()==oleo.getId()),"Consultas não usam a mesma regra.");ok("Catálogo, busca por nome e manutenção de produtos usam a mesma regra");
   exigir(!esperado.contains(inativo.getId()) && !esperado.contains(categoriaInativa.getId()) && dao.listarManutencao("antigo pesquisa oleo").stream().anyMatch(p->p.getId()==inativo.getId()),"Ativação/arquivo incorretos.");ok("Loja preserva filtros de ativos; manutenção mantém acesso aos inativos");
   exigir(ids("%").equals(Set.of(kit.getId())) && ids("_").equals(Set.of(kit.getId())) && ids("' OR 1=1--").equals(ids("or 1")) && ids("or 1").size()<ids("").size(),"Curingas/injeção alteraram busca.");ok("Percentual/sublinhado literais e valores preparados não ampliam a consulta");
   exigir(ids(null).equals(ids("")) && ids("\u00a0 \t").equals(ids("")) && ids("xyzprodutoausente").isEmpty() && ids("oleo cacao pesquisa").isEmpty(),"Vazio/termos ausentes incorretos.");ok("Busca vazia lista o catálogo, e todos os termos informados são necessários");
  }else{
   Set<Integer> oleos=ids("oleo");exigir(!oleos.isEmpty(),"Óleo não encontrado na base local.");for(String t:new String[]{"ÓLEO","  OLEO ","o\u0301leo"})exigir(ids(t).equals(oleos),"Acentos/caixa divergentes na base local.");exigir(ids("argan oleo").equals(ids("oleo argan")) && !ids("argan oleo").isEmpty(),"Palavras fora de ordem falharam.");
  }
  String antes=estado();Cliente cliente=new ClienteLojaDAO().autenticar("cliente@demo.local","cliente123");Sessao.iniciarCliente(cliente);
  if(!local){try{dao.listarManutencao("oleo");throw new AssertionError("Cliente acessou manutenção.");}catch(SQLException esperado){}ok("Permissão da manutenção permanece protegida");}
  SwingUtilities.invokeAndWait(()->{loja=new TelaLoja(cliente);loja.addNotify();loja.validate();});aguardar(()->temTexto(loja,"produtos encontrados"));
  String termo=local?"oleo":"oleo pesquisa argan";int qtd=dao.listarCatalogo(termo).size();SwingUtilities.invokeAndWait(()->{campo().setText(termo);botao("Filtrar").doClick();});aguardar(()->temTexto(loja,qtd==1?"1 produto encontrado":qtd+" produtos encontrados"));
  SwingUtilities.invokeAndWait(()->{exigir(temTexto(loja,"Óleo"),"Cartão não apareceu.");try{imagem(local?"busca-oleo-base-local.png":"busca-oleo.png");}catch(Exception e){throw new RuntimeException(e);}if(!local){campo().setText("pesq ARG ole");botao("Filtrar").doClick();}});if(!local)aguardar(()->temTexto(loja,"1 produto encontrado"));
  SwingUtilities.invokeAndWait(()->{for(Window w:Window.getWindows())w.dispose();Sessao.encerrar();});exigir(antes.equals(estado()),"Busca modificou nomes/preços/saldo ou pedidos.");if(!local)ok("Filtro Swing mostra produto sem acentos e preserva os dados");System.out.println(local?"APROVADO: oleo/ÓLEO/Unicode/espaços/palavras fora de ordem na base local, produto exibido na loja e dados preservados.":"APROVADO: "+casos+" cenários de busca de produtos em PostgreSQL real e Swing.");System.exit(0);
 }
 private static Produto produto(String nome,int cat,boolean ativo)throws Exception{Produto p=new Produto();p.setNome(nome);p.setPreco(new BigDecimal("25.50"));p.setIdCategoria(cat);p.setAtivo(ativo);p.setEstoqueInicial(10);dao.salvar(p);return p;}
 private static Set<Integer> ids(String busca)throws SQLException{Set<Integer> ids=new HashSet<>();for(var p:dao.listarCatalogo(busca))ids.add(p.produto().getId());return ids;}
 private static String estado()throws SQLException{return texto("SELECT concat((SELECT md5(string_agg(row(id,nome,preco,ativo)::text,',' ORDER BY id)) FROM produtos),':',(SELECT SUM(quantidade) FROM estoque),':',(SELECT COUNT(*) FROM pedidos),':',(SELECT COUNT(*) FROM movimentos_estoque))");}
 private static JTextField campo(){return achar(loja,JTextField.class,"loja-busca");}private static JButton botao(String n){return achar(loja,JButton.class,n);}
 private static <T extends Component>T achar(Container c,Class<T> tipo,String n){for(Component f:c.getComponents()){if(tipo.isInstance(f) && (n.equals(f.getName()) || f instanceof AbstractButton && n.equals(((AbstractButton)f).getText())))return tipo.cast(f);if(f instanceof Container){T r=achar((Container)f,tipo,n);if(r!=null)return r;}}return null;}
 private static boolean temTexto(Container c,String n){for(Component f:c.getComponents()){if(f instanceof JLabel && ((JLabel)f).getText().contains(n))return true;if(f instanceof Container && temTexto((Container)f,n))return true;}return false;}
 private static void aguardar(BooleanSupplier b)throws Exception{CountDownLatch l=new CountDownLatch(1);SwingUtilities.invokeAndWait(()->{javax.swing.Timer t=new javax.swing.Timer(100,null);t.addActionListener(e->{if(b.getAsBoolean()){t.stop();l.countDown();}});t.start();});exigir(l.await(30,TimeUnit.SECONDS),"Catálogo não concluiu consulta.");}
 private static void layout(Container c){c.doLayout();for(Component f:c.getComponents())if(f instanceof Container)layout((Container)f);}
 private static void imagem(String nome)throws Exception{Container p=loja.getContentPane();layout(p);BufferedImage b=new BufferedImage(p.getWidth(),p.getHeight(),BufferedImage.TYPE_INT_RGB);Graphics2D g=b.createGraphics();try{p.printAll(g);}finally{g.dispose();}ImageIO.write(b,"png",Path.of("docs/validacao-ui",nome).toFile());}
 private static String texto(String s)throws SQLException{try(Connection c=ConexaoBanco.getConexao();Statement p=c.createStatement();ResultSet r=p.executeQuery(s)){r.next();return r.getString(1);}}private static void sql(String s)throws SQLException{try(Connection c=ConexaoBanco.getConexao();Statement p=c.createStatement()){p.execute(s);}}
 private static void exigir(boolean b,String s){if(!b)throw new AssertionError(s);}private static void ok(String s){casos++;System.out.println("OK "+casos+": "+s);}
}
